21	/** Options controlling side effects mountForms() triggers beyond the DOM/state update itself. */
22	export interface MountFormsOptions {
23	  /**
24	   * Called after every state-mutating interaction, once `setState` has
25	   * already been invoked with the new state — mirrors matrix-interactions.ts's
26	   * MountOptions.onChange.
27	   */
28	  onChange?: () => void;
29	}
30	
31	/**
32	 * Regenerates `#staged-commands`'s textarea content from `getState()` via
33	 * `toCommandLines` (./model): one line per entry, in `toCommandLines`'s
34	 * order, `#`-prefixed when `valid` is `false`. Exported so it's directly
35	 * testable without going through a form submission.
36	 */
37	export function regenerateStagedCommands(container: HTMLElement, getState: () => PendingState): void {
38	  const textarea = container.querySelector("#staged-commands");
39	  if (!(textarea instanceof HTMLTextAreaElement)) return;
40	  const lines = toCommandLines(getState()).map((cl) => (cl.valid ? cl.line : `# ${cl.line}`));
41	  textarea.value = lines.join("\n");
42	}
43	
44	/**
45	 * Returns a copy of `base` with every `added*`/`updated*` collection reset to
46	 * empty, keeping all `base*` snapshot arrays untouched. Mirrors the shape of
47	 * model.test.ts's `emptyState` helper, but is its own implementation since
48	 * that helper is private to that test file.
49	 */
50	export function emptyPendingState(base: PendingState): PendingState {
51	  return {
52	    baseAttractors: base.baseAttractors,
53	    baseComponents: base.baseComponents,
54	    baseForces: base.baseForces,
55	    basePersonas: base.basePersonas,
56	    baseTerms: base.baseTerms,
57	    addedAttractors: [],
58	    addedComponents: [],
59	    addedForces: [],
60	    addedPersonas: [],
61	    addedTerms: [],
62	    updatedAttractors: {},
63	    updatedComponents: {},
64	    updatedForces: {},
65	    updatedPersonas: {},
66	    updatedTerms: {},
67	  };
68	}
69	
70	/** Reads a named text input's trimmed-nothing raw value from `form`, defaulting to "" if absent. */
71	function readInput(form: HTMLFormElement, name: string): string {
72	  const input = form.querySelector<HTMLInputElement>(`[name="${name}"]`);
73	  return input?.value ?? "";
74	}
75	
76	/**
77	 * Attaches all live-editing interactions for the below-matrix "Stage adds"
78	 * forms, the two visibility toggles, and the staged-commands textarea/copy/
79	 * clear controls to `container` (an already-present element containing the
80	 * four `form[data-command-generator]` elements, the toolbar checkboxes, the
81	 * `table.matrix`, `#staged-commands`, `#copy-staged`, and `#clear-staged`).
82	 *
83	 * `getState`/`setState` give this module read/write access to the
84	 * caller-owned `PendingState` without owning it directly, mirroring
85	 * matrix-interactions.ts's `mount` signature.
86	 */
87	export function mountForms(
88	  container: HTMLElement,
89	  getState: () => PendingState,
90	  setState: (next: PendingState) => void,
91	  options?: MountFormsOptions,
92	): void {
93	  function regenerate(): void {
94	    regenerateStagedCommands(container, getState);
95	  }
96	
97	  function wireForceForm(kind: "stressor" | "purpose"): void {
98	    const form = container.querySelector<HTMLFormElement>(`form[data-command-generator="${kind}"]`);
99	    if (form === null) return;
100	    form.addEventListener("submit", (event) => {
101	      event.preventDefault();
102	      const { state: withRow, tempId } = addForceRow(getState(), kind);
103	      let next = withRow;
104	
105	      const fieldMap: Array<[string, "description" | "attractorId" | "naiveChangeOrFeature" | "shortname" | "outcomes"]> = [
106	        ["description", "description"],
107	        ["attractor_id", "attractorId"],
108	        ["naive_change", "naiveChangeOrFeature"],
109	        ["shortname", "shortname"],
110	        ["outcomes", "outcomes"],
111	      ];
112	      for (const [formName, field] of fieldMap) {
113	        const value = readInput(form, formName);
114	        if (value !== "") {
115	          next = updateForceField(next, tempId, field, value);
116	        }
117	      }
118	
119	      setState(next);
120	      form.reset();
121	      regenerate();
122	      options?.onChange?.();
123	    });
124	  }
125	
126	  function maxExistingAttractorSuffix(state: PendingState): number {
127	    let max = 0;
128	    for (const a of state.addedAttractors) {
129	      const match = /^NEW-ATTR-(\d+)$/.exec(a.id);
130	      if (match) {
131	        const n = Number(match[1]);
132	        if (n > max) max = n;
133	      }
134	    }
135	    return max;
136	  }
137	
138	  function wireAttractorForm(): void {
139	    const form = container.querySelector<HTMLFormElement>('form[data-command-generator="attractor"]');
140	    if (form === null) return;
141	    form.addEventListener("submit", (event) => {
142	      event.preventDefault();
143	      const state = getState();
144	      const id = `NEW-ATTR-${maxExistingAttractorSuffix(state) + 1}`;
145	      const next = addAttractorOption(state, {
146	        id,
147	        name: readInput(form, "name"),
148	        description: readInput(form, "description"),
149	        positiveState: readInput(form, "positive_state"),
150	        negativeState: readInput(form, "negative_state"),
151	      });
152	      setState(next);
153	      form.reset();
154	      regenerate();
155	      options?.onChange?.();
156	    });
157	  }
158	
159	  function setComponentFormError(form: HTMLFormElement, message: string): void {
160	    const errorEl = container.querySelector("[data-component-form-error]");
161	    if (errorEl) errorEl.textContent = message;
162	    form.querySelector<HTMLInputElement>('[name="name"]')?.setAttribute("aria-invalid", "true");
163	  }
164	
165	  function clearComponentFormError(form: HTMLFormElement): void {
166	    const errorEl = container.querySelector("[data-component-form-error]");
167	    if (errorEl) errorEl.textContent = "";
168	    form.querySelector<HTMLInputElement>('[name="name"]')?.removeAttribute("aria-invalid");
169	  }
170	
171	  function insertComponentColumn(name: string): void {
172	    const table = container.querySelector("table.matrix");
173	    if (table === null) return;
174	
175	    const headerRow = table.querySelector("thead tr");
176	    if (headerRow !== null) {
177	      const th = document.createElement("th");
178	      th.className = "sticky-row";
179	      th.setAttribute("data-component", name);
180	      th.textContent = name;
181	      const cornerRight = headerRow.querySelector("th.sticky-col-right");
182	      if (cornerRight !== null) {
183	        headerRow.insertBefore(th, cornerRight);
184	      } else {
185	        headerRow.appendChild(th);
186	      }
187	    }
188	
189	    for (const row of Array.from(table.querySelectorAll("tbody tr.force-row"))) {
190	      const forceId = row.getAttribute("data-force-id") ?? "";
191	      const td = document.createElement("td");
192	      td.setAttribute("data-residue-cell", "true");
193	      td.setAttribute("data-force-id", forceId);
194	      td.setAttribute("data-component", name);
195	      td.setAttribute("data-coupled", "0");
196	      const cornerRight = row.querySelector("td.sticky-col-right");
197	      if (cornerRight !== null) {
198	        row.insertBefore(td, cornerRight);
199	      } else {
200	        row.appendChild(td);
201	      }
202	    }
203	
204	    const footerRow = table.querySelector("tfoot tr");
205	    if (footerRow !== null) {
206	      const td = document.createElement("td");
207	      td.setAttribute("data-col-total", "0");
208	      td.setAttribute("data-component", name);
209	      td.textContent = "0";
210	      const cornerRight = footerRow.querySelector("td.sticky-col-right");
211	      if (cornerRight !== null) {
212	        footerRow.insertBefore(td, cornerRight);
213	      } else {
214	        footerRow.appendChild(td);
215	      }
216	    }
217	  }
218	
219	  function wireComponentForm(): void {
220	    const form = container.querySelector<HTMLFormElement>('form[data-command-generator="component"]');
221	    if (form === null) return;
222	    form.addEventListener("submit", (event) => {
223	      event.preventDefault();
224	      const name = readInput(form, "name");
225	      try {
226	        const next = addComponentColumn(getState(), {
227	          name,
228	          description: readInput(form, "description"),
229	          status: readInput(form, "status") === "proposed" ? "proposed" : "actual",
230	          architectureSet: readInput(form, "architecture_set"),
