273	    unrelatedToggle?.addEventListener("change", applyVisibility);
274	  }
275	
276	  function wireClearButton(): void {
277	    const clearButton = container.querySelector("#clear-staged");
278	    clearButton?.addEventListener("click", () => {
279	      setState(emptyPendingState(getState()));
280	      regenerate();
281	      options?.onChange?.();
282	    });
283	  }
284	
285	  function wireCopyButton(): void {
286	    const copyButton = container.querySelector("#copy-staged");
287	    copyButton?.addEventListener("click", () => {
288	      const textarea = container.querySelector("#staged-commands");
289	      const value = textarea instanceof HTMLTextAreaElement ? textarea.value : "";
290	      const clipboard = typeof navigator === "undefined" ? undefined : navigator.clipboard;
291	      if (clipboard?.writeText) {
292	        void clipboard.writeText(value);
293	      }
294	    });
295	  }
