297	  wireForceForm("stressor");
298	  wireForceForm("purpose");
299	  wireAttractorForm();
300	  wireComponentForm();
301	  wireVisibilityToggles();
302	  wireClearButton();
303	  wireCopyButton();
304	
305	  regenerate();
306	}
